type nat = u32;

fn find_smallest(s: &Vec<nat>) -> Option<nat> {
    if s.is_empty() {
        return None;
    }
    // Initialize min with the first element
    let mut min = s[0];
    // Iterate over the rest and update min when a smaller value is found
    for &val in s.iter().skip(1) {
        if val < min {
            min = val;
        }
    }
    Some(min)
}

fn main() {
    let empty: Vec<nat> = vec![];
    let nums = vec![5, 3, 8, 1, 4];

    assert_eq!(find_smallest(&empty), None);
    assert_eq!(find_smallest(&nums), Some(1));
    println!("All tests passed!");
}